//go:build windows

package desync

import (
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"syscall"
	"unsafe"
)

const supportsUDPFake = true

func configureUDPFake(raw syscall.RawConn) error {
	var operationErr error
	err := raw.Control(func(fd uintptr) {
		socket := syscall.Handle(fd)
		kind, err := getsockoptInt(socket, syscall.SOL_SOCKET, 0x1008) // Winsock SO_TYPE
		if err != nil || kind != syscall.SOCK_DGRAM {
			operationErr = ErrUDPFakeRequiresSocket
			return
		}
		// SIO_UDP_NETRESET: suppress ICMP TTL-expired errors generated by our
		// intentional low-TTL packets. It affects only this owned UDP socket.
		var disabled, returned uint32
		operationErr = syscall.WSAIoctl(socket, 0x9800000f, (*byte)(unsafe.Pointer(&disabled)), 4, nil, 0, &returned, nil, 0)
	})
	if operationErr != nil {
		operationErr = os.NewSyscallError("SIO_UDP_NETRESET", operationErr)
	}
	return errors.Join(err, operationErr)
}

func sendUDPFake(pc net.PacketConn, raw syscall.RawConn, opts UDPOptions, addr net.Addr) (unsafeTTL bool, err error) {
	var operationErr error
	controlErr := raw.Control(func(fd uintptr) {
		socket := syscall.Handle(fd)
		// UDP sockets can be IPv6-only. Winsock may allow reading an IPv4
		// option on them but reject setting it; select by the destination's
		// actual address family instead of changing both socket options.
		option := savedTTL{level: syscall.IPPROTO_IPV6, option: syscall.IPV6_UNICAST_HOPS}
		if udp, ok := addr.(*net.UDPAddr); ok && udp.IP.To4() != nil {
			option.level, option.option = syscall.IPPROTO_IP, syscall.IP_TTL
		}
		old, getErr := getsockoptInt(socket, option.level, option.option)
		if getErr != nil {
			operationErr = os.NewSyscallError("read UDP TTL", getErr)
			return
		}
		option.value = old
		if setErr := syscall.SetsockoptInt(socket, option.level, option.option, opts.TTL); setErr != nil {
			operationErr = os.NewSyscallError("set UDP fake TTL", setErr)
			unsafeTTL = true
			return
		}
		for i := 0; i < opts.Repeats; i++ {
			n, sendErr := pc.WriteTo(opts.Payload, addr)
			if sendErr == nil && n != len(opts.Payload) {
				sendErr = io.ErrShortWrite
			}
			if sendErr != nil {
				operationErr = sendErr
				break
			}
			opts.Counters.fakes.Add(1)
		}
		if restoreErr := restoreFakeTTL(socket, []savedTTL{option}); restoreErr != nil {
			unsafeTTL = true
			operationErr = errors.Join(operationErr, fmt.Errorf("desync: restore UDP TTL: %w", restoreErr))
		}
	})
	return unsafeTTL, errors.Join(controlErr, operationErr)
}
